function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function parseMatrix(t){
  return splitLines(t).map(function(l){ return l.split('|').map(function(c){return c.trim();}).filter(function(c,idx){ return idx===0 || c.length>0; }); });
}
function buildCompetitive(o){
  o=o||{};
  var product=String(o.product||'').trim()||'（自家产品）';
  var competitors=splitLines(o.competitors);
  var dims=splitLines(o.dimensions);
  var rows=parseMatrix(o.matrix).filter(function(r){return r.length>=2;});
  var maxCols=0; rows.forEach(function(r){ if(r.length>maxCols) maxCols=r.length; });
  var compN=Math.max(0, maxCols-1, competitors.length);
  var labels=[];
  if(competitors.length===compN){ labels=competitors.slice(); }
  else { for(var i=0;i<compN;i++){ labels.push(competitors[i]||('竞品'+(i+1))); } }
  var lines=[];
  lines.push('# 竞品对比分析：'+product);
  lines.push('');
  lines.push('## 一、对比对象');
  lines.push('- 自家产品：'+product);
  if(labels.length){ lines.push('- 竞品：'+labels.join('、')); }
  else { lines.push('- 竞品：（待补充）'); }
  lines.push('');
  lines.push('## 二、对比维度');
  if(dims.length){ dims.forEach(function(d){ lines.push('- '+d); }); }
  else { lines.push('- （待补充对比维度，如 价格 / 功能 / 性能 / 生态）'); }
  lines.push('');
  if(rows.length){
    lines.push('## 三、对比矩阵');
    var header='| 维度 | 自家('+product+') | '+labels.join(' | ')+' |';
    var sep='| --- | --- | '+labels.map(function(){return '---';}).join(' | ')+' |';
    lines.push(header); lines.push(sep);
    rows.forEach(function(r){
      var cells=r.slice(1);
      while(cells.length<labels.length){ cells.push('（待填）'); }
      lines.push('| '+r[0]+' | '+cells.join(' | ')+' |');
    });
    lines.push('');
    lines.push('## 四、结论与建议');
    lines.push('- 差异化优势：（待补充）');
    lines.push('- 待补齐短板：（待补充）');
  } else {
    lines.push('## 三、对比矩阵（骨架）');
    lines.push('> 在「对比矩阵」中按「维度 | 自家 | 竞品1 | 竞品2」逐行填写，即可生成完整矩阵。');
    if(dims.length){ lines.push(''); dims.forEach(function(d){ lines.push('- '+d+'：| （待填） | （待填） | （待填） |'); }); }
  }
  return {title:product+' 竞品对比', dimCount:dims.length, compCount:labels.length, rowCount:rows.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, parseMatrix:parseMatrix, buildCompetitive:buildCompetitive};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CompetitiveForgePure = EXPORTS; }
